defmodule Vault.Ledger.AccountState do
  defstruct account_id: nil, owner: nil, balance_cents: 0, status: :absent, version: 0,
            deposit_count: 0, withdrawal_count: 0, last_event_type: nil, last_recorded_at: nil

  @type t :: %__MODULE__{}
end

defmodule Vault.Ledger.Fold do
  def initial(account_id), do: %Vault.Ledger.AccountState{account_id: account_id}

  def apply_event(%Vault.Ledger.AccountState{account_id: state_id} = state, %Vault.Ledger.Event{} = event) do
    cond do
      state_id != nil and state_id != event.account_id ->
        {:error, {:account_mismatch, state_id, event.account_id}}

      event.version != state.version + 1 ->
        {:error, {:version_gap, state.version + 1, event.version}}

      not (event.payload.type in [:account_opened, :deposited, :withdrawn, :frozen, :unfrozen]) ->
        {:error, {:unknown_event_type, event.payload.type}}

      true ->
        apply_success(state, event)
    end
  end

  defp apply_success(state, event) do
    data = event.payload.value

    new_state = case event.payload.type do
      :account_opened ->
        if state.status != :absent, do: {:error, :already_open}
        else
          {:ok, %{state | owner: data.owner, balance_cents: data.opening_balance_cents, status: :open}}
        end

      :deposited ->
        cond do
          state.status == :absent -> {:error, :account_absent}
          state.status == :frozen -> {:error, :account_frozen}
          true -> {:ok, %{state | balance_cents: state.balance_cents + data.amount_cents, deposit_count: state.deposit_count + 1}}
        end

      :withdrawn ->
        cond do
          state.status == :absent -> {:error, :account_absent}
          state.status == :frozen -> {:error, :account_frozen}
          state.balance_cents < data.amount_cents -> {:error, :insufficient_funds}
          true -> {:ok, %{state | balance_cents: state.balance_cents - data.amount_cents, withdrawal_count: state.withdrawal_count + 1}}
        end

      :frozen ->
        if state.status != :open, do: {:error, :not_open}
        else
          {:ok, %{state | status: :frozen}}
        end

      :unfrozen ->
        if state.status != :frozen, do: {:error, :not_frozen}
        else
          {:ok, %{state | status: :open}}
        end
    end

    case new_state do
      {:error, reason} -> {:error, reason}
      {:ok, s} ->
        {:ok, %{s | version: event.version, last_event_type: event.payload.type, last_recorded_at: event.recorded_at}}
    end
  end

  def replay(state, events) do
    Enum.reduce_while(events, {:ok, state}, fn {event, i}, {:ok, acc} ->
      case apply_event(acc, event) do
        {:ok, next} -> {:cont, {:ok, next}}
        {:error, reason} -> {:halt, {:error, reason}}
      end
    end)
  end

  # Wrapper for replay with index check
  def replay_indexed(state, events) do
    events
    |> Enum.with_index()
    |> Enum.reduce_while({:ok, state, nil}, fn {event, i}, {:ok, acc, last_seq} ->
      if last_seq != nil and event.sequence <= last_seq do
        {:halt, {:error, {:out_of_order, i}}}
      else
        case apply_event(acc, event) do
          {:ok, next} -> {:cont, {:ok, next, event.sequence}}
          {:error, reason} -> {:halt, {:error, reason}}
        end
      end
    end)
    |> case do
      {:ok, state, _} -> {:ok, state}
      {:error, reason} -> {:error, reason}
    end
  end

  # We'll use apply_event in commands, and for audit we'll fold. For audit: fold from initial and track each step.
  # But wait, audit needs to show per-event diff. Let's create an audit fold.
  def audit_fold(state, events) do
    # returns a list of diff maps, ascending
    {rev_diffs, _final_state, _ok?} =
      Enum.reduce_while(events, {[], state, true}, fn {event, i}, {acc, curr_state, _ok} ->
        bal_before = curr_state.balance_cents
        stat_before = curr_state.status
        case apply_event(curr_state, event) do
          {:ok, next} ->
            diff = %{sequence: event.sequence, version: event.version, type: event.payload.type,
                     balance_before: bal_before, balance_after: next.balance_cents, delta_cents: next.balance_cents - bal_before,
                     status_before: stat_before, status_after: next.status, recorded_at: event.recorded_at}
            {:cont, {[diff | acc], next, true}}
          {:error, reason} ->
            {:halt, {acc, curr_state, {:error, {:fold_failed, event.sequence, reason}}}}
        end
      end)

    case Enum.reverse(rev_diffs) do
      [] -> {:ok, []}
      [head | _] ->
        # Wait, the return for audit is the list of diff maps. If fold fails, need to surface error.
        # Let's rework to return {:ok, list} or {:error, reason}.
        nil
    end
  end
end

defmodule Vault.Ledger.Fold do
  @spec initial(String.t()) :: Vault.Ledger.AccountState.t()
  def initial(account_id), do: %Vault.Ledger.AccountState{account_id: account_id}

  @doc "Apply one event to a state, with precedence-based rejection and no storage access."
  @spec apply_event(Vault.Ledger.AccountState.t(), Vault.Ledger.Event.t()) ::
    {:ok, Vault.Ledger.AccountState.t()} | {:error, any()}
  def apply_event(%Vault.Ledger.AccountState{account_id: state_id} = state, %Vault.Ledger.Event{} = event) do
    cond do
      state_id != nil and state_id != event.account_id ->
        {:error, {:account_mismatch, state_id, event.account_id}}

      event.version != state.version + 1 ->
        {:error, {:version_gap, state.version + 1, event.version}}

      not (event.payload.type in [:account_opened, :deposited, :withdrawn, :frozen, :unfrozen]) ->
        {:error, {:unknown_event_type, event.payload.type}}

      true ->
        apply_success(state, event)
    end
  end

  defp apply_success(state, event) do
    data = event.payload.value

    new_state = case event.payload.type do
      :account_opened ->
        if state.status != :absent, do: {:error, :already_open}
        else
          {:ok, %{state | owner: data.owner, balance_cents: data.opening_balance_cents, status: :open}}
        end

      :deposited ->
        cond do
          state.status == :absent -> {:error, :account_absent}
          state.status == :frozen -> {:error, :account_frozen}
          true -> {:ok, %{state | balance_cents: state.balance_cents + data.amount_cents, deposit_count: state.deposit_count + 1}}
        end

      :withdrawn ->
        cond do
          state.status == :absent -> {:error, :account_absent}
          state.status == :frozen -> {:error, :account_frozen}
          state.balance_cents < data.amount_cents -> {:error, :insufficient_funds}
          true -> {:ok, %{state | balance_cents: state.balance_cents - data.amount_cents, withdrawal_count: state.withdrawal_count + 1}}
        end

      :frozen ->
        if state.status != :open, do: {:error, :not_open}
        else
          {:ok, %{state | status: :frozen}}
        end

      :unfrozen ->
        if state.status != :frozen, do: {:error, :not_frozen}
        else
          {:ok, %{state | status: :open}}
        end
    end

    case new_state do
      {:error, reason} -> {:error, reason}
      {:ok, s} ->
        {:ok, %{s | version: event.version, last_event_type: event.payload.type, last_recorded_at: event.recorded_at}}
    end
  end

  @doc """
  Replays a list of events onto `state` and returns `{:ok, state}` or `{:error, reason}`.
  Rejects unsorted input: returns `{:error, {:out_of_order, i}}` where `i` is the
  zero-based position of the first event whose `sequence` is not strictly greater
  than its predecessor\'s. Empty list returns `state` unchanged. This order check
  happens before any event is applied.
  \"\"\"
  @spec replay(Vault.Ledger.AccountState.t(), [Vault.Ledger.Event.t()]) ::
    {:ok, Vault.Ledger.AccountState.t()} | {:error, any()}
  def replay(state, events) do
    events
    |> Enum.with_index()
    |> Enum.reduce_while({:ok, state, nil}, fn {event, i}, {:ok, acc, last_seq} ->
      if last_seq != nil and event.sequence <= last_seq do
        {:halt, {:error, {:out_of_order, i}}}
      else
        case apply_event(acc, event) do
          {:ok, next} -> {:cont, {:ok, next, event.sequence}}
          {:error, reason} -> {:halt, {:error, reason}}
        end
      end
    end)
    |> case do
      {:ok, state, _} -> {:ok, state}
      {:error, reason} -> {:error, reason}
    end
  end

  @doc "Like `replay/2` but returns the full diff list per event."
  def audit_fold(state, events) do
    Enum.reduce_while(events, {[], state}, fn event, {acc, curr} ->
      bal_before = curr.balance_cents
      stat_before = curr.status
      case apply_event(curr, event) do
        {:ok, next} ->
          diff = %{sequence: event.sequence, version: event.version, type: event.payload.type,
                   balance_before: bal_before, balance_after: next.balance_cents, delta_cents: next.balance_cents - bal_before,
                   status_before: stat_before, status_after: next.status, recorded_at: event.recorded_at}
          {:cont, {[diff | acc], next}}
        {:error, reason} ->
          {:halt, {acc, {:error, {:fold_failed, event.sequence, reason}}}}
      end
    end)
    |> case do
      {acc, {:error, reason}} -> {:error, reason}
      {acc, _} -> {:ok, Enum.reverse(acc)}
    end
  end
end

